import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Login.css';
import HomeIcon from '../Common/HomeIcon';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
  
    if (!email || !password) {
      alert('Completează toate câmpurile!');
      return;
    }
  
    fetch('http://localhost:8080/users/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ email, password })
    })
      .then(res => {
        if (!res.ok) {
          throw new Error("Autentificare eșuată!");
        }
        return res.text();
      })
      .then(data => {
        alert(data);  
        setSubmitted(true);
      })
      .catch(error => {
        alert(error.message);
      });
  };
  

  return (
    <div className="login-container">
      
      < HomeIcon />
      <h1>Login</h1>

      <form onSubmit={handleSubmit}>
        <input type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)}/>
        <input type="password"  placeholder="Parolă"  value={password} onChange={(e) => setPassword(e.target.value)}/>
        <button type="submit">Login</button>

        <p style={{ textAlign: 'center', marginTop: '15px' }}> Nu ai un cont? <Link to="/register">Înregistrează-te</Link></p>
      </form>

      { 
       submitted && ( <p style={{ color: 'green' }}>Te-ai logat cu succes!</p> )
      }
      
    </div>
  );
}

export default Login;
